module parity_8bit (
    input [7:0] in,
    output out
);

wire [3:0] temp;
assign temp[0] = in[0] ^ in[1];
assign temp[1] = in[2] ^ in[3];
assign temp[2] = in[4] ^ in[5];
assign temp[3] = in[6] ^ in[7];
assign out = ^temp;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_s0, not_s1;
    wire term0, term1, term2, term3;

    not(not_s0, sel[0]);
    not(not_s1, sel[1]);

    and(term0, in[0], not_s1, not_s0);
    and(term1, in[1], not_s1, sel[0]);
    and(term2, in[2], sel[1], not_s0);
    and(term3, in[3], sel[1], sel[0]);

    or(out, term0, term1, term2, term3);
endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    assign equal = (a == b);
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

assign out[0] = (in == 2'b00);
assign out[1] = (in == 2'b01);
assign out[2] = (in == 2'b10);
assign out[3] = (in == 2'b11);

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3])
        code = 2'b11;
    else if (in[2])
        code = 2'b10;
    else if (in[1])
        code = 2'b01;
    else
        code = 2'b00; // Handles all-zero input
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    localparam MAX = 2'd2;
    reg [1:0] counter;

    assign state = counter;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 2'd0;
        end else if (counter == MAX) begin
            counter <= 2'd0;
        end else begin
            counter <= counter + 1'b1;
        end
    end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Define state parameters
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    reg [1:0] current_state, next_state;

    // State register (sequential logic)
    always @(posedge clk) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next state logic (combinational)
    always @(*) begin
        case (current_state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0; // Handle unexpected states
        endcase
    end

    // Output logic (combinational)
    always @(*) begin
        case (current_state)
            S0: light = 3'b100;
            S1: light = 3'b010;
            S2: light = 3'b001;
            default: light = 3'b000; // Default case
        endcase
    end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10,
              S3 = 2'b11;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        case (current_state)
            S0: next_state = (up_request && !down_request) ? S1 : S0;
            S1: next_state = (down_request && !up_request) ? S2 : S1;
            S2: next_state = (up_request && !down_request) ? S3 : S2;
            S3: next_state = (down_request && !up_request) ? S0 : S3;
            default: next_state = S0;
        endcase
    end

    assign state = current_state;
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

localparam [1:0] STATE_INIT = 2'b00,
                 STATE_FLOOR1 = 2'b01,
                 STATE_FLOOR2 = 2'b10;

reg [1:0] state, next_state;

// State register with asynchronous reset
always @(posedge clk, posedge reset) begin
    if (reset) state <= STATE_INIT;
    else state <= next_state;
end

// Next state logic
always @(*) begin
    case (state)
        STATE_INIT: next_state = coin_inserted ? STATE_FLOOR1 : STATE_INIT;
        STATE_FLOOR1: next_state = (~coin_inserted) ? STATE_INIT : STATE_FLOOR1;
        STATE_FLOOR2: begin
            if (~item_selected)
                next_state = STATE_INIT;
            else if (coin_inserted)
                next_state = STATE_FLOOR2;
            else
                next_state = STATE_FLOOR1;
        end
        default: next_state = STATE_INIT;
    endcase
end

assign state = state;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

    wire signed [3:0] neg_val0 = -in_0;
    wire signed [3:0] result = in_1 * neg_val0;
    assign out = { {12{result[3]}}, result };

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire [3:0] digit3 = (in_0[15:12] >= 4'sd0 && in_0[15:12] <= 4'sd9) ? in_0[15:12] : 4'sd0;
wire [3:0] digit2 = (in_0[11:8]  >= 4'sd0 && in_0[11:8]  <= 4'sd9) ? in_0[11:8]  : 4'sd0;
wire [3:0] digit1 = (in_0[7:4]   >= 4'sd0 && in_0[7:4]   <= 4'sd9) ? in_0[7:4]   : 4'sd0;
wire [3:0] digit0 = (in_0[3:0]   >= 4'sd0 && in_0[3:0]   <= 4'sd9) ? in_0[3:0]   : 4'sd0;

wire valid = (digit3 <= 4'sd9) && (digit2 <= 4'sd9) && (digit1 <= 4'sd9) && (digit0 <= 4'sd9);

assign out = valid ? {4'b0, digit3, digit2, digit1, digit0} : 8'sd0;

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    assign out = a + b;
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);

wire [7:0] pp0, pp1, pp2, pp3;

assign pp0 = {4'b0, (a & {4{b[0]}})} << 0;
assign pp1 = {4'b0, (a & {4{b[1]}})} << 1;
assign pp2 = {4'b0, (a & {4{b[2]}})} << 2;
assign pp3 = {4'b0, (a & {4{b[3]}})} << 3;

assign #100 out = pp0 + pp1 + pp2 + pp3;

endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);

    wire signed [7:0] sum;
    assign sum = a + b; // Sum computation (may wrap around)

    // Extension to 9-bit signed
    assign diff = {sum[7], sum};

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

assign out = in << shift;

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);

    assign out = ~in;

endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

// Stage 1: Shift by 1 bit if shift[0] is set
wire [7:0] stage1 = shift[0] ? {in[6:0], 1'b0} : in;

// Stage 2: Shift by 2 bits if shift[1] is set
wire [7:0] stage2 = shift[1] ? {stage1[5:0], 2'b00} : stage1;

// Stage 3: Shift by 4 bits if shift[2] is set
wire [7:0] shifted = shift[2] ? {stage2[3:0], 4'h0} : stage2;

// Stage 4: Add 8'h1B if no shifts occurred (shift == 3'b000)
wire [7:0] final_out = (shift == 3'b000) ? {4'h1, 4'hB} : shifted;

assign out = final_out;

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);
    assign out = in_0 >> 6;
endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [3:0] sum_bits;
    assign sum_bits[0] = data_in[1] ^ data_in[0];
    assign sum_bits[1] = data_in[2] ^ (data_in[1] | data_in[0]);
    assign sum_bits[2] = data_in[3] ^ (data_in[2] & (data_in[1] | data_in[0]));
    assign sum_bits[3] = data_in[4] ^ (data_in[3] | (data_in[2] & (data_in[1] | data_in[0])));

    assign data_out[7:4] = sum_bits;
    assign data_out[3:0] = ~data_in[3:0];
endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    // XOR each byte with the reversed KEY extended to 8 bits
    assign data_out = data_in ^ {4'b0, KEY};
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg [7:0] counter;

    always @(posedge clk) begin
        if (rst)
            counter <= 8'b0;
        else
            counter <= counter + 1;
    end

    assign clk_out = counter[0];
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq;
    wire [3:0] gt;
    wire [3:0] lt;
    wire E_total, G_total, L_total;

    // Equality bits (XNOR)
    assign eq[0] = ~(a[0] ^ b[0]);
    assign eq[1] = ~(a[1] ^ b[1]);
    assign eq[2] = ~(a[2] ^ b[2]);
    assign eq[3] = ~(a[3] ^ b[3]);

    // Greater than bits (a > b)
    assign gt[0] = ~b[0];
    assign gt[1] = ~b[1] & eq[0];
    assign gt[2] = ~b[2] & eq[1] & eq[0];
    assign gt[3] = ~b[3] & eq[2] & eq[1] & eq[0];

    // Less than bits (a < b)
    assign lt[0] = b[0];
    assign lt[1] = b[1] & eq[0];
    assign lt[2] = b[2] & eq[1] & eq[0];
    assign lt[3] = b[3] & eq[2] & eq[1] & eq[0];

    // Total comparisons
    assign E_total = &eq;
    assign G_total = |gt;
    assign L_total = |lt;;

    // Outputs
    assign gt = E_total | G_total;
    assign eq = E_total | L_total;
    assign lt = E_total;
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    assign out[0] = enable & (in == 2'h0);
    assign out[1] = enable & (in == 2'h1);
    assign out[2] = enable & (in == 2'h2);
    assign out[3] = enable & (in == 2'h3);

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);

    assign out[0] = enable & ~in[1] & ~in[0];
    assign out[1] = enable & ~in[1] &  in[0];
    assign out[2] = enable &  in[1] & ~in[0];
    assign out[3] = enable &  in[1] &  in[0];

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);
    wire notD = ~in;

    assign out0 = notD & sel;
    assign out1 = in & sel;
endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    // Select signals based on sel (active low)
    assign out0 = (sel == 2'b00) ? in : 1'b0;
    assign out1 = (sel == 2'b01) ? in : 1'b0;

    // Default assignments for unspecified outputs (requires input configuration)
    assign out2 = 1'bx; // Define input condition if needed
    assign out3 = 1'bx; // Define input condition if needed

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [7:0] binary_counter;

always @(posedge clk) begin
    if (rst)
        binary_counter <= 8'b0;
    else
        binary_counter <= binary_counter + 1;
end

assign count[7] = binary_counter[4] ^ binary_counter[7];
assign count[6] = binary_counter[3] ^ binary_counter[7];
assign count[5] = binary_counter[2] ^ binary_counter[7];
assign count[4] = binary_counter[1] ^ binary_counter[7];
assign count[3] = binary_counter[0] ^ binary_counter[7];
assign count[2] = binary_counter[5] ^ binary_counter[6];
assign count[1] = binary_counter[4] ^ binary_counter[6];
assign count[0] = binary_counter[3] ^ binary_counter[6];

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] temp;

always @(posedge clk) begin
    if (rst) begin
        temp <= 4'b0;
    end else begin
        temp <= { ~temp[0], temp[3:1] };
    end
end

assign q = temp;

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst)
        shift_reg <= 8'b0;
    else if (load)
        shift_reg <= pin;
    else
        shift_reg <= shift_reg << 1;
end

assign sout = shift_reg[7];

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] state;

assign q = state;

always @(posedge clk) begin
    if (rst) begin
        state <= 4'b0001;
    end else begin
        state <= {state[2:0], state[3]};
    end
end

endmodule

module sipo_8bit(
    input clk,
