);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], sin};
    end
end

assign pout = shift_reg;

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);

reg [6:0] q;

always @(posedge clk) begin
    if (rst) begin
        q <= 7'b0;
    end else begin
