module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (reset) begin
      q <= 4'd9;
    end else if (q == 4'd0) begin
      q <= 4'd9;
    end else begin
      q <= q - 1'b1;
    end
  end

