module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State definitions
  localparam [1:0] STATE_0 = 2'b00,
                   STATE_1 = 2'b01,
                   STATE_2 = 2'b10,
                   STATE_3 = 2'b11;

  reg [1:0] current_state, next_state;

  // Sequential state transition with asynchronous areset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= STATE_1;
    else
      current_state <= next_state;
  end

  // Combinational next state logic
  always @(*) begin
    next_state = current_state; // Default: remain in current state
    if (train_valid && ~train_taken) begin
      case (current_state)
        STATE_0: next_state = STATE_1;
        STATE_1: next_state = STATE_2;
        STATE_2: next_state = STATE_3;
        STATE_3: next_state = STATE_0;
        default: next_state = STATE_1;
      endcase
    end
  end

