module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10;

  reg [1:0] current_state, next_state;

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    next_state = current_state;
    z = 1'b0;

    case (current_state)
      S0: begin
        if (x) begin
          next_state = S1;
          z = 1'b0;
        end else begin
          next_state = S0;
          z = 1'b0;
        end
      end
      S1: begin
        if (x) begin
          next_state = S2;
          z = 1'b0;
        end else begin
          next_state = S0;
          z = 1'b1;
        end
      end
      S2: begin
        if (x) begin
          next_state = S2;
          z = 1'b0;
        end else begin
          next_state = S0;
          z = 1'b1;
        end
      end
      default: begin
        next_state = S0;
        z = 1'b0;
      end
    endcase
  end

endmodule

