  wire and_ab;

  // Compute sum (a XOR b)
  not(not_a, a);
  not(not_b, b);
  and(a_and_not_b, a, not_b);
  and(b_and_not_a, b, not_a);
  or(sum, a_and_not_b, b_and_not_a);

