module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] P, G;
  wire c1, c2, c3, c4;
  wire [3:0] carry;

  assign P = x ^ y;
  assign G = x & y;

  // Carry look-ahead logic
  assign carry[0] = G[0]; // c1
  assign carry[1] = G[1] | (P[1] & G[0]); // c2
  assign carry[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]); // c3
  assign carry[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]); // c4

  // Sum calculation
  assign sum[0] = P[0];          // 0 carry in
  assign sum[1] = P[1] ^ carry[0];
  assign sum[2] = P[2] ^ carry[1];
  assign sum[3] = P[3] ^ carry[2];
  assign sum[4] = carry[3];     // Carry-out

endmodule

