      S0: next_state = reset ? S1 : S0;
      S1: next_state = reset ? S1 : S2;
      S2: next_state = reset ? S3 : S0;
      S3: next_state = reset ? S4 : S2;
      S4: next_state = reset ? S1 : S2;
