  // Next state logic
  always @* begin
    case (state_reg)
      IDLE: 
        state_next = (a && b) ? HAVENTREDCOIN : IDLE;
      HAVENTREDCOIN: 
        state_next = (a && b) ? HAVENTREDCOIN : IDLE;
