);

  assign out = state[3];

  always @(*) begin
    if (in)
      next_state = 4'b0000;
    else
      next_state = state[3] ? 4'b1000 :
               state[2] ? 4'b0100 :
               state[1] ? 4'b0010 :
               state[0] ? 4'b0001 :
               4'b0000;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  input in,
  output disc,
  output flag,
  output err
);

  localparam IDLE      = 3'd0,
             WRITE_T0  = 3'd1,
             WRITE_T1  = 3'd2,
             WRITE_T2  = 3'd3,
             WRITE_T3  = 3'd4,
             WRITE_T4  = 3'd5,
             WRITE_T5  = 3'd6,
             READ_T0   = 3'd7;

  reg [2:0] current_state, next_state;

  always @(posedge clk) begin
    if (reset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE:    next_state = in ? WRITE_T0 : IDLE;
      WRITE_T0: next_state = WRITE_T1;
      WRITE_T1: next_state = WRITE_T2;
      WRITE_T2: next_state = WRITE_T3;
      WRITE_T3: next_state = WRITE_T4;
      WRITE_T4: next_state = WRITE_T5;
      WRITE_T5: next_state = READ_T0;
      READ_T0: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  assign disc = (current_state == READ_T0);
  assign flag  = (current_state == WRITE_T0);
  assign err  = (current_state == WRITE_T5);

endmodule

module TopModule (
