module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  parameter S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10,
           S3 = 2'b11;

  reg [1:0] current_state, next_state;
  reg get_signal;

  always @(posedge clk) begin
    if (reset) begin
      current_state <= S0;
      get_signal <= 1'b0;
    end else begin
      current_state <= next_state;
      case (current_state)
        S0: get_signal <= 1'b0;
        S1: get_signal <= 1'b0;
        S2: get_signal <= in[3];
        S3: get_signal <= 1'b0;
        default: get_signal <= 1'b0;
      endcase
    end
  end

  always @(*) begin
    case (current_state)
      S0: next_state = (in[3] == 1'b0) ? S1 : S3;
      S1: next_state = (in[3] == 1'b1) ? S2 : S0;
      S2: next_state = S3;
      S3: next_state = S3;
      default: next_state = S0;
    endcase
  end

  assign done = get_signal;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  reg [2:0] cnt;
  reg [1:0] state, next_state;
  reg [2:0] max_count;

  // State definitions
  localparam IDLE = 2'b00;
  localparam RUN  = 2'b01;
  localparam WAIT = 2'b10;

  // State transition
  always @(posedge clk) begin
    if (in)
      state <= IDLE;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      IDLE: next_state = reset ? RUN : IDLE;
      RUN:  next_state = (cnt == max_count) ? WAIT : RUN;
      WAIT: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Max count determination
  always @(*) begin
    case (state)
      IDLE: max_count = reset ? 3'd5 : 3'd0;
      RUN:  max_count = (reset == 0) ? 3'd0 : 3'd5;
      WAIT: max_count = 3'd0;
      default: max_count = 3'd0;
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (in)
      cnt <= 3'd0;
    else begin
      case (state)
        IDLE: cnt <= 3'd0;
        RUN:  cnt <= (cnt == max_count) ? 3'd0 : cnt + 1;
        WAIT: cnt <= 3'd0;
        default: cnt <= 3'd0;
      endcase
    end
  end

  // Output assignment
  assign done = (state == WAIT);

endmodule

module TopModule (
