  wire term1, term2, term3;

  not (not_a0, a);
  not (not_a1, b);
  not (not_a2, c);
  not (not_a3, d);

  and (term1, not_a1, c, not_a3);
  and (term2, not_a0, not_a2, d);
  and (term3, a, not_a1, not_a2);

  or (out, term1, term2, term3);

endmodule

