module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  reg state_reg, next_state;
  parameter IDLE = 1'b0, FLIP = 1'b1;

  // State register with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      state_reg <= IDLE;
    else
      state_reg <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state_reg)
      IDLE:   next_state = bump_left ? FLIP : IDLE;
      FLIP:   next_state = bump_right    ? IDLE : FLIP;
      default: next_state = IDLE;
    endcase
  end

  // Output assignments
  assign walk_right  = (state_reg == FLIP);
  assign walk_left = ~walk_right;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam STATE_IDLE = 2'b00,
             STATE_VHF  = 2'b01,
             STATE_CHF  = 2'b10,
             STATE_HRF  = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= STATE_IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      STATE_IDLE: 
        next_state = bump_left ? STATE_VHF : STATE_IDLE;
      STATE_VHF: 
        next_state = bump_right ? STATE_CHF : STATE_VHF;
      STATE_CHF: 
        next_state = ground ? STATE_HRF : STATE_CHF;
      STATE_HRF: 
        next_state = bump_left ? STATE_VHF : STATE_HRF;
      default: 
        next_state = STATE_IDLE;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == STATE_IDLE);
  assign walk_right = (current_state == STATE_CHF);
  assign aaah  = (current_state == STATE_VHF) || (current_state == STATE_HRF);

endmodule

