module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg alarm_reg;

  always @(posedge reset) begin
    if (data) begin
      shift_reg <= 3'b000;
      alarm_reg <= 1'b0;
    end else begin
      // Update shift register with new temperature reading
      shift_reg <= {shift_reg[1:0], clk};

      // Check if new reading is 0 (within 17-19 range)
      if (!clk) begin
        alarm_reg <= 1'b1;
      end else if (shift_reg == 3'b000) begin
        alarm_reg <= 1'b0;
      end
    end
  end

  assign start_shifting = alarm_reg;

endmodule

