module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // State definitions
  localparam [2:0] 
    test_empty      = 3'd0,
    test_empty_prev = 3'd1,
    test_full       = 3'd2,
    test_full_prev  = 3'd3,
    write           = 3'd4,
    read           = 3'd5;

  reg [2:0] current_state, next_state;

  // State register with synchronous reset
  always @(posedge clk) begin
    if (resetn)
      current_state <= test_empty;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      test_empty:
        next_state = x ? test_full : test_empty_prev;
      test_empty_prev:
        next_state = test_empty;
      test_full:
        next_state = y ? test_empty : test_full_prev;
      test_full_prev:
        next_state = test_full;
      write:
        next_state = x ? write : read;
      read:
        next_state = y ? read : test_empty;
      default:
        next_state = test_empty;
    endcase
  end

  // Output logic (Moore style)
  assign f  = (current_state == write);
  assign g = (current_state == read);

endmodule

module TopModule (
