  always @(posedge clk) begin
    if (x)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      s0: next_state = x ? s1 : s0;
      s1: next_state = x ? s1 : s2;
      s2: next_state = x ? s1 : s0;
      default: next_state = s0;
    endcase
  end

  assign z = (current_state == s2) && (x == 0);

endmodule

module TopModule (
  input clk,
  input areset,
  input x,
  output z
);

parameter [1:0] state0 = 2'b00,
                state1 = 2'b01,
                state2 = 2'b11,
                state3 = 2'b10;

reg [1:0] current_state, next_state;

// State register with asynchronous reset
always @(posedge clk or posedge areset) begin
  if (areset)
    current_state <= state0;
  else
    current_state <= next_state;
end

// Next state logic
always @(*) begin
  case (current_state)
    state0: next_state = x ? state1 : state0;
    state1: next_state = state2;
    state2: next_state = state3;
    state3: next_state = state3;
    default: next_state = state0;
  endcase
end

// Output logic (Mealy-type)
assign z = (current_state == state1) ? ~x : x;

endmodule

